base.writer_schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:rp-wiki:writer-output:1",
  "title": "Wiki Writer common output v1",
  "$comment": "V2 (1.0.1): existing-identity and informational diagnostics are valid issues.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "request_ref",
    "documents",
    "metric_ops",
    "people_ops",
    "issues"
  ],
  "properties": {
    "schema_version": {
      "const": 1
    },
    "request_ref": {
      "type": "string",
      "pattern": "^req:[A-Za-z0-9_-]+$",
      "maxLength": 160
    },
    "documents": {
      "type": "array",
      "maxItems": 32,
      "items": {
        "$ref": "#/$defs/document"
      }
    },
    "metric_ops": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/metricOperation"
      }
    },
    "people_ops": {
      "type": "array",
      "maxItems": 32,
      "items": {
        "$ref": "#/$defs/peopleOperation"
      }
    },
    "issues": {
      "type": "array",
      "maxItems": 32,
      "items": {
        "$ref": "#/$defs/issue"
      }
    }
  },
  "$defs": {
    "documentRef": {
      "type": "string",
      "pattern": "^(doc|new):[A-Za-z0-9_-]+$",
      "maxLength": 160
    },
    "actorRef": {
      "description": "A target reference is either actor:user or a trusted Character document reference from the current catalog, including a same-response new Character document reference.",
      "anyOf": [
        {
          "$ref": "#/$defs/documentRef"
        },
        {
          "const": "actor:user"
        }
      ]
    },
    "entryRef": {
      "type": "string",
      "pattern": "^entry:[A-Za-z0-9_-]+$",
      "maxLength": 160
    },
    "sourceRef": {
      "type": "string",
      "pattern": "^source:[A-Za-z0-9_-]+$",
      "maxLength": 160
    },
    "evidenceRefs": {
      "type": "array",
      "minItems": 1,
      "maxItems": 32,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/sourceRef"
      }
    },
    "targetRefs": {
      "type": "array",
      "maxItems": 16,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/actorRef"
      }
    },
    "textSlot": {
      "type": "string",
      "minLength": 1,
      "maxLength": 160
    },
    "metricSlot": {
      "type": "string",
      "minLength": 1,
      "maxLength": 160
    },
    "reason": {
      "type": "string",
      "minLength": 1,
      "maxLength": 800
    },
    "aliases": {
      "type": "array",
      "maxItems": 32,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 160
      }
    },
    "tags": {
      "type": "array",
      "maxItems": 64,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 120,
        "pattern": "^(?!_|feature:|slot:|owner:|layer:).+$"
      }
    },
    "entryUpsert": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "operation",
        "entry_ref",
        "slot_id",
        "target_refs",
        "context_key",
        "label",
        "assertion",
        "text",
        "evidence_refs",
        "links",
        "reason"
      ],
      "properties": {
        "operation": {
          "const": "upsert"
        },
        "entry_ref": {
          "anyOf": [
            {
              "$ref": "#/$defs/entryRef"
            },
            {
              "type": "null"
            }
          ]
        },
        "slot_id": {
          "$ref": "#/$defs/textSlot"
        },
        "target_refs": {
          "$ref": "#/$defs/targetRefs"
        },
        "context_key": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 120
        },
        "label": {
          "type": "string",
          "minLength": 1,
          "maxLength": 160
        },
        "assertion": {
          "enum": [
            "fact",
            "belief",
            "assessment"
          ]
        },
        "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 4000
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "links": {
          "type": "array",
          "maxItems": 32,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/documentRef"
          }
        },
        "reason": {
          "$ref": "#/$defs/reason"
        }
      }
    },
    "entryRemove": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "operation",
        "entry_ref",
        "slot_id",
        "evidence_refs",
        "reason"
      ],
      "properties": {
        "operation": {
          "const": "remove"
        },
        "entry_ref": {
          "$ref": "#/$defs/entryRef"
        },
        "slot_id": {
          "$ref": "#/$defs/textSlot"
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "reason": {
          "$ref": "#/$defs/reason"
        }
      }
    },
    "storyDate": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "text",
        "precision",
        "calendar",
        "anchor_event_ref"
      ],
      "properties": {
        "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 200
        },
        "precision": {
          "enum": [
            "exact",
            "relative",
            "approximate",
            "unknown"
          ]
        },
        "calendar": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 120
        },
        "anchor_event_ref": {
          "anyOf": [
            {
              "$ref": "#/$defs/documentRef"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "if": {
        "properties": {
          "precision": {
            "const": "unknown"
          }
        },
        "required": [
          "precision"
        ]
      },
      "then": {
        "properties": {
          "text": {
            "const": "미상"
          },
          "calendar": {
            "type": "null"
          },
          "anchor_event_ref": {
            "type": "null"
          }
        }
      }
    },
    "storyTime": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "text",
        "precision"
      ],
      "properties": {
        "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 200
        },
        "precision": {
          "enum": [
            "exact",
            "period",
            "relative",
            "approximate",
            "unknown"
          ]
        }
      },
      "if": {
        "properties": {
          "precision": {
            "const": "unknown"
          }
        },
        "required": [
          "precision"
        ]
      },
      "then": {
        "properties": {
          "text": {
            "const": "미상"
          }
        }
      }
    },
    "eventEnd": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "date",
        "time"
      ],
      "properties": {
        "date": {
          "$ref": "#/$defs/storyDate"
        },
        "time": {
          "$ref": "#/$defs/storyTime"
        }
      }
    },
    "place": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "document_ref"
      ],
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 240
        },
        "document_ref": {
          "anyOf": [
            {
              "$ref": "#/$defs/documentRef"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "if": {
        "properties": {
          "name": {
            "const": "미상"
          }
        },
        "required": [
          "name"
        ]
      },
      "then": {
        "properties": {
          "document_ref": {
            "type": "null"
          }
        }
      }
    },
    "eventContext": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "date",
        "time",
        "end",
        "places",
        "evidence_refs"
      ],
      "properties": {
        "date": {
          "$ref": "#/$defs/storyDate"
        },
        "time": {
          "$ref": "#/$defs/storyTime"
        },
        "end": {
          "anyOf": [
            {
              "$ref": "#/$defs/eventEnd"
            },
            {
              "type": "null"
            }
          ]
        },
        "places": {
          "type": "array",
          "minItems": 1,
          "maxItems": 16,
          "items": {
            "$ref": "#/$defs/place"
          }
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        }
      }
    },
    "document": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "operation",
        "type",
        "title",
        "aliases_add",
        "aliases_remove",
        "tags_add",
        "tags_remove",
        "event_context",
        "entries"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "operation": {
          "enum": [
            "create",
            "update"
          ]
        },
        "type": {
          "enum": [
            "character",
            "event",
            "scene",
            "location",
            "faction",
            "item",
            "concept",
            "other"
          ]
        },
        "title": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 160
        },
        "aliases_add": {
          "$ref": "#/$defs/aliases"
        },
        "aliases_remove": {
          "$ref": "#/$defs/aliases"
        },
        "tags_add": {
          "$ref": "#/$defs/tags"
        },
        "tags_remove": {
          "$ref": "#/$defs/tags"
        },
        "event_context": {
          "anyOf": [
            {
              "$ref": "#/$defs/eventContext"
            },
            {
              "type": "null"
            }
          ]
        },
        "entries": {
          "type": "array",
          "maxItems": 128,
          "items": {
            "oneOf": [
              {
                "$ref": "#/$defs/entryUpsert"
              },
              {
                "$ref": "#/$defs/entryRemove"
              }
            ]
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "operation": {
                "const": "create"
              }
            },
            "required": [
              "operation"
            ]
          },
          "then": {
            "required": [
              "title",
              "entries"
            ],
            "properties": {
              "document_ref": {
                "pattern": "^new:"
              },
              "title": {
                "type": "string"
              },
              "aliases_remove": {
                "maxItems": 0
              },
              "tags_remove": {
                "maxItems": 0
              },
              "entries": {
                "minItems": 1,
                "items": {
                  "allOf": [
                    {
                      "$ref": "#/$defs/entryUpsert"
                    },
                    {
                      "properties": {
                        "entry_ref": {
                          "type": "null"
                        }
                      }
                    }
                  ]
                }
              }
            }
          },
          "else": {
            "properties": {
              "document_ref": {
                "pattern": "^doc:"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "event"
              }
            },
            "required": [
              "type"
            ]
          },
          "then": {
            "required": [
              "event_context"
            ],
            "properties": {
              "event_context": {
                "$ref": "#/$defs/eventContext"
              }
            }
          },
          "else": {
            "properties": {
              "event_context": {
                "type": "null"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "create"
              },
              "type": {
                "const": "character"
              }
            },
            "required": [
              "operation",
              "type"
            ]
          },
          "then": {
            "properties": {
              "entries": {
                "contains": {
                  "type": "object",
                  "properties": {
                    "operation": {
                      "const": "upsert"
                    },
                    "slot_id": {
                      "const": "core.current_state"
                    }
                  },
                  "required": [
                    "operation",
                    "slot_id"
                  ]
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "create"
              },
              "type": {
                "const": "event"
              }
            },
            "required": [
              "operation",
              "type"
            ]
          },
          "then": {
            "properties": {
              "entries": {
                "contains": {
                  "type": "object",
                  "properties": {
                    "operation": {
                      "const": "upsert"
                    },
                    "slot_id": {
                      "const": "core.event_summary"
                    }
                  },
                  "required": [
                    "operation",
                    "slot_id"
                  ]
                }
              }
            }
          }
        }
      ]
    },
    "metricEvent": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "amount",
        "evidence_refs",
        "evidence_quote",
        "reason"
      ],
      "properties": {
        "amount": {
          "type": "number"
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "evidence_quote": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1000
        },
        "reason": {
          "$ref": "#/$defs/reason"
        }
      }
    },
    "metricInit": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "slot_id",
        "target_refs",
        "operation",
        "value",
        "evidence_refs",
        "reason"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "slot_id": {
          "$ref": "#/$defs/metricSlot"
        },
        "target_refs": {
          "$ref": "#/$defs/targetRefs"
        },
        "operation": {
          "const": "init"
        },
        "value": {
          "type": "number"
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "reason": {
          "$ref": "#/$defs/reason"
        },
        "context_key": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 160
        }
      }
    },
    "metricDelta": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "slot_id",
        "target_refs",
        "operation",
        "events"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "slot_id": {
          "$ref": "#/$defs/metricSlot"
        },
        "target_refs": {
          "$ref": "#/$defs/targetRefs"
        },
        "operation": {
          "const": "delta"
        },
        "events": {
          "type": "array",
          "minItems": 1,
          "maxItems": 32,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/metricEvent"
          }
        },
        "context_key": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 160
        }
      }
    },
    "metricTransition": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "slot_id",
        "target_refs",
        "operation",
        "name",
        "evidence_refs",
        "reason"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "slot_id": {
          "$ref": "#/$defs/metricSlot"
        },
        "target_refs": {
          "$ref": "#/$defs/targetRefs"
        },
        "operation": {
          "const": "transition"
        },
        "name": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9_-]*$",
          "maxLength": 80
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "reason": {
          "$ref": "#/$defs/reason"
        },
        "context_key": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 160
        }
      }
    },
    "metricDerive": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "slot_id",
        "target_refs",
        "operation",
        "choices",
        "evidence_refs",
        "reason"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "slot_id": {
          "$ref": "#/$defs/metricSlot"
        },
        "target_refs": {
          "$ref": "#/$defs/targetRefs"
        },
        "operation": {
          "const": "derive"
        },
        "choices": {
          "type": "object",
          "minProperties": 1,
          "maxProperties": 16,
          "propertyNames": {
            "pattern": "^[a-z][a-z0-9_]*$"
          },
          "additionalProperties": {
            "type": "string",
            "minLength": 1,
            "maxLength": 120
          }
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "reason": {
          "$ref": "#/$defs/reason"
        },
        "context_key": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "maxLength": 160
        }
      }
    },
    "metricOperation": {
      "oneOf": [
        {
          "$ref": "#/$defs/metricInit"
        },
        {
          "$ref": "#/$defs/metricDelta"
        },
        {
          "$ref": "#/$defs/metricTransition"
        },
        {
          "$ref": "#/$defs/metricDerive"
        }
      ]
    },
    "peopleOperation": {
      "oneOf": [
        {
          "$ref": "#/$defs/peopleInit"
        },
        {
          "$ref": "#/$defs/peopleObserve"
        }
      ]
    },
    "peopleAxes": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "relationalInitiative",
        "expressionDirectness",
        "emotionalExpressiveness",
        "guardedness",
        "impulsivity",
        "relationshipPersistence"
      ],
      "properties": {
        "relationalInitiative": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "expressionDirectness": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "emotionalExpressiveness": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "guardedness": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "impulsivity": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "relationshipPersistence": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        }
      }
    },
    "peopleInit": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "operation",
        "summary",
        "core_traits",
        "values",
        "emotion_expression",
        "defense_response",
        "intimacy_style",
        "axes",
        "evidence_refs",
        "reason"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "operation": {
          "const": "init"
        },
        "summary": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1600
        },
        "core_traits": {
          "type": "array",
          "maxItems": 20,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 160
          }
        },
        "values": {
          "type": "array",
          "maxItems": 20,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 160
          }
        },
        "emotion_expression": {
          "type": "string",
          "minLength": 1,
          "maxLength": 700
        },
        "defense_response": {
          "type": "string",
          "minLength": 1,
          "maxLength": 700
        },
        "intimacy_style": {
          "type": "string",
          "minLength": 1,
          "maxLength": 700
        },
        "axes": {
          "$ref": "#/$defs/peopleAxes"
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "reason": {
          "$ref": "#/$defs/reason"
        }
      }
    },
    "peopleObserve": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_ref",
        "operation",
        "axis",
        "direction",
        "pattern",
        "strength",
        "confidence",
        "scene_key",
        "evidence_refs",
        "evidence_quote",
        "reason"
      ],
      "properties": {
        "document_ref": {
          "$ref": "#/$defs/documentRef"
        },
        "operation": {
          "const": "observe"
        },
        "axis": {
          "enum": [
            "relationalInitiative",
            "expressionDirectness",
            "emotionalExpressiveness",
            "guardedness",
            "impulsivity",
            "relationshipPersistence",
            "qualitative"
          ]
        },
        "direction": {
          "enum": [
            "increase",
            "decrease",
            "new_pattern",
            "weaken_pattern"
          ]
        },
        "pattern": {
          "type": "string",
          "maxLength": 500
        },
        "strength": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "confidence": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "scene_key": {
          "type": "string",
          "minLength": 1,
          "maxLength": 160
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
        "evidence_quote": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1000
        },
        "reason": {
          "$ref": "#/$defs/reason"
        }
      }
    },
    "issue": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "code",
        "document_ref",
        "detail"
      ],
      "properties": {
        "code": {
          "enum": [
            "missing_context",
            "ambiguous_identity",
            "evidence_conflict",
            "incomplete_contract",
            "no_canonical_change",
            "identity_resolved_existing",
            "note"
          ]
        },
        "document_ref": {
          "anyOf": [
            {
              "$ref": "#/$defs/documentRef"
            },
            {
              "type": "null"
            }
          ]
        },
        "detail": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1000
        }
      }
    }
  }
}

base.director_schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:rp-wiki:director-output:1",
  "title": "Director output v1",
  "$comment": "Narrow request_ref, allowed tools, source refs, planning features and completed checks per request. On pass 2 allow final only.",
  "oneOf": [{"$ref":"#/$defs/final"},{"$ref":"#/$defs/needContext"}],
  "$defs": {
    "requestRef": {"type":"string","pattern":"^req:[A-Za-z0-9_-]+$","maxLength":160},
    "sourceRef": {"type":"string","pattern":"^(doc|source):[A-Za-z0-9_-]+$","maxLength":160},
    "documentRef": {"type":"string","pattern":"^doc:[A-Za-z0-9_-]+$","maxLength":160},
    "planningFeature": {"enum":["rhythm"]},
    "completedCheck": {"enum":["rhythm.macro_reviewed"]},
    "searchTool": {"enum":["chat_search","wiki_search","lore_search"]},
    "search": {
      "type":"object","additionalProperties":false,
      "required":["tool","query","reason"],
      "properties": {
        "tool":{"$ref":"#/$defs/searchTool"},
        "query":{"type":"string","minLength":1,"maxLength":600},
        "reason":{"type":"string","minLength":1,"maxLength":500}
      }
    },
    "planningNote": {
      "type":"object","additionalProperties":false,
      "required":["feature","document_ref","text"],
      "properties": {
        "feature":{"$ref":"#/$defs/planningFeature"},
        "document_ref":{"anyOf":[{"$ref":"#/$defs/documentRef"},{"type":"null"}]},
        "text":{"type":"string","minLength":1,"maxLength":1500}
      }
    },
    "final": {
      "type":"object","additionalProperties":false,
      "required":["schema_version","request_ref","decision","note","uncertainties","used_refs","planning_notes","completed_checks"],
      "properties": {
        "schema_version":{"const":1},"request_ref":{"$ref":"#/$defs/requestRef"},"decision":{"const":"final"},
        "note":{"type":"string","minLength":1,"maxLength":12000},
        "uncertainties":{"type":"array","maxItems":24,"items":{"type":"string","minLength":1,"maxLength":600}},
        "used_refs":{"type":"array","maxItems":64,"uniqueItems":true,"items":{"$ref":"#/$defs/sourceRef"}},
        "planning_notes":{"type":"array","maxItems":8,"items":{"$ref":"#/$defs/planningNote"}},
        "completed_checks":{"type":"array","maxItems":8,"uniqueItems":true,"items":{"$ref":"#/$defs/completedCheck"}}
      }
    },
    "needContext": {
      "type":"object","additionalProperties":false,
      "required":["schema_version","request_ref","decision","searches","provisional_constraints"],
      "properties": {
        "schema_version":{"const":1},"request_ref":{"$ref":"#/$defs/requestRef"},"decision":{"const":"need_context"},
        "searches":{"type":"array","minItems":1,"maxItems":8,"uniqueItems":true,"items":{"$ref":"#/$defs/search"}},
        "provisional_constraints":{"type":"array","maxItems":24,"items":{"type":"string","minLength":1,"maxLength":600}}
      }
    }
  }
}
